def defects(H,F,s,l,rd,rp,rc,dz,ds,dl):
 a=[np.asarray(v,dtype=np.longdouble) for v in [H,F,s,l,rd,rp,rc,dz,ds,dl]];H,F,s,l,rd,rp,rc,dz,ds,dl=a
