def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());d=np.load(REPO/s['reduced']['path']);a=np.load(REPO/s['output']['path']);parent=json.loads((REPO/s['source']['path']).read_text());r=load_ritz(json.loads((REPO/parent['source']['path']).read_text()));part=json.loads((REPO/s['partition_source']['path']).read_text());partdata=np.load(REPO/part['output']['path']);v=partdata['physical_probe'];V=np.column_stack([r['V'],v]);P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);x=r['before_x'];B=A@V;H=V.T@(P@V);g=V.T@(P@x+p['q']);eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ine=~eq;N,cp,unit=d['N'],d['cp'],float(d['unit']);rs=1/np.maximum(np.max(abs(B),axis=1),1e-15);HH=N.T@H@N/unit;gg=N.T@(g+H@cp)/unit;F=(rs[ine,None]*B[ine])@N;b=rs[ine]*((A@x-p['lower'])[ine]+B[ine]@cp)
 checks=dict(all2208rows=A.shape[0]==2208,original131columns=V.shape[1]==131,original130retained=np.array_equal(V[:,:130],r['V']),actual_probe=np.array_equal(v,d['probe']),physical_H=float(np.max(abs(HH-d['H'])))<1e-7,physical_g=float(np.max(abs(gg-d['g'])))<1e-10,original_F=float(np.max(abs(F-d['F'])))<1e-10,original_finite_gap_b=float(np.max(abs(b-d['b'])))<1e-10,equality_particular=float(np.max(abs(B[eq]@cp-(p['lower']-A@x)[eq])))<1e-10,equality_nullspace=float(np.max(abs(B[eq]@N)))<1e-10,physical_regularization=s['physical_regularization']==0)
 # Rigid vectors retained unchanged; orthogonal vector scaled work and curvature independently measured.
 D=partdata['D'];Z=r['V']/D[:,None];w=v/D;probe_metrics=dict(rigid37_orthogonality=float(np.max(abs(Z[:,:37].T@w))),all130_orthogonality=float(np.max(abs(Z.T@w))),curvature_Nmm=float(v@(P@v)),work_Nmm=float(partdata['physical_residual']@v),maximum_original_row_motion=float(np.max(abs(A@v))));checks['elastic_enrichment']=probe_metrics['all130_orthogonality']<1e-8 and probe_metrics['curvature_Nmm']>0
 # Audit each saved direction using original first-order equations, before elimination.
 z,ss,ll=[d[k].copy() for k in ['z0','s0','l0']];hist=json.loads((REPO/s['history']['path']).read_text());direction_audits=[];controls=[];accepted_count=0
 for h in hist:
  e=np.load(src.parent/('direction%02d.npz'%h['iteration']));rd=HH@z+gg-F.T@ll;rp=F@z+b-ss;mu=float(ss@ll/len(ss));ea=defects(HH,F,ss,ll,rd,rp,ss*ll,e['predictor_dz'],e['predictor_ds'],e['predictor_dl']);rc=ss*ll+e['predictor_ds']*e['predictor_dl']-float(e['sigma'])*mu
  # On predictor rejection producer stores rc_predictor as unused corrector rhs.
  if max(ea)>=1e-8:rc=ss*ll
  ec=defects(HH,F,ss,ll,rd,rp,rc,e['dz'],e['ds'],e['dl']);cert=max(ea+ec)<1e-8
  same=max(float(np.max(abs(z-e['z']))),float(np.max(abs(ss-e['s']))),float(np.max(abs(ll-e['l']))))<1e-10
  alpha=float(e['alpha']);zz=z+alpha*e['dz'];sss=ss+alpha*e['ds'];lll=ll+alpha*e['dl'];merit=max(float(np.max(abs(rd))),float(np.max(abs(rp))),mu);merit1=max(float(np.max(abs(HH@zz+gg-F.T@lll))),float(np.max(abs(F@zz+b-sss))),float(sss@lll/len(ss)));can=cert and np.min(sss)>0 and np.min(lll)>0 and merit1<=(1-1e-4*alpha)*merit
  checks['direction_%02d'%h['iteration']]=bool(same and cert==h['certified'] and bool(e['accepted'])==h['accepted'] and (not h['accepted'] or can))
  direction_audits.append(dict(iteration=h['iteration'],predictor=ea,corrector=ec,certified=cert,accepted=h['accepted'],merit=merit,merit_after=merit1))
  controls.append(dict(reversed_dual=float(np.max(abs(HH@e['dz']+F.T@e['dl']+rd))),reversed_finitegap=float(np.max(abs(F@e['dz']-e['ds']+rp-2*b))),omitted_row=float(np.max(abs(F[int(np.argmax(abs(e['dl'])))]*np.max(abs(e['dl'])))))))
