 checks['trajectory_endpoint']=max(float(np.max(abs(z-a['z']))),float(np.max(abs(ss-a['s']))),float(np.max(abs(ll-a['l']))))<1e-10;checks['certified_count']=accepted_count==s['certified_algorithmic_steps'];checks['negative_controls']=all(all(v>1e-8 for v in c.values()) for c in controls)
 e=np.load(REPO/s['archived_corrector']['path']);arc=defects(e['H'],e['F'],e['s'],e['l'],e['rd'],e['rp'],e['rc'],e['dz'],e['ds'],e['dl']);checks['archived_corrector_classification']=(max(arc)<1e-8)==s['archived_metrics']['corrector_certified']
