 checks.update(physical_duals=float(np.max(abs(expected_y-y)))<1e-8,actual_endpoint=float(np.max(abs(proposal-a['proposed_x'])))<1e-12,actual_physical_force=float(np.max(abs(res-a['physical_residual'])))<1e-8,endpoint_guard=accepted==s['endpoint_finitegap_armijo_accepted'],physical_qualification=qualified==s['physical_KKT_qualified'],no_nonlinear_update=s['actual_support_updates']==0)
 cad=json.loads((REPO/s['candidate']['path']).read_text());checks['actual78STEP_hashes']=len(cad['part_references'])==78 and all(sha(REPO/v['path'])==v['SHA256'] for v in cad['part_references'].values());checks['input_hashes']=all(sha(REPO/s[k]['path'])==s[k]['SHA256'] for k in ['candidate','source','source_field','physical_P','physical_A','problem','partition_source','reduced','output','archived_corrector','history']);ok=all(checks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_CERTIFIED_CENTRALITY_AUDIT_PASS' if ok else 'ACTUAL_P1_CERTIFIED_CENTRALITY_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},direction_audits=direction_audits,negative_controls=controls,archived_corrector_errors=arc,probe_metrics=probe_metrics,metrics=metrics,physical_KKT_qualified=bool(qualified),endpoint_guard=accepted,actual_support_updates=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start));print(json.dumps(dict(checks=checks,metrics=metrics,archived_corrector=arc),default=bool));raise SystemExit(0 if ok else 2)
